INSERT INTO `alur_kerja` VALUES (1,'1','Catat dokumen','Isi data surat (nomor, tanggal, perihal) dan unggah berkas pindaian bila tersedia.','Dokumen tercatat di sistem.',0,'2026-10-31 04:52:13','2026-10-31 04:52:13'),(2,'2','Tetapkan lokasi penyimpanan','Pilih ruang, rak, dan boks sesuai tempat fisik berkas, lalu simpan penempatan tersebut.','Lokasi dokumen diketahui saat dibutuhkan.',1,'2026-10-31 04:52:13','2026-10-31 04:52:13'),(3,'3','Kelola peminjaman dan penelusuran','Cari dokumen lewat pencarian, catat peminjaman bila dipinjam, dan kembalikan setelah selesai dipakai.','Status dan riwayat dokumen tetap terpantau.',2,'2026-10-31 04:52:13','2026-10-31 04:52:13');
